2	// This package has no build tags, making it usable by all test packages.
3	package testutil
4	
5	import (
6		"errors"
7		"os"
8		"os/exec"
9		"path/filepath"
10		"strings"
11		"sync"
12		"testing"
13		"time"
14	
15		"github.com/go-git/go-git/v6"
16		"github.com/go-git/go-git/v6/plumbing"
17		"github.com/go-git/go-git/v6/plumbing/format/config"
18		"github.com/go-git/go-git/v6/plumbing/object"
19	)
20	
21	// RewindPoint mirrors the rewind --list JSON output.
22	type RewindPoint struct {
23		ID               string    `json:"id"`
24		Message          string    `json:"message"`
25		MetadataDir      string    `json:"metadata_dir"`
26		Date             time.Time `json:"date"`
27		IsTaskCheckpoint bool      `json:"is_task_checkpoint"`
28		ToolUseID        string    `json:"tool_use_id"`
29		IsLogsOnly       bool      `json:"is_logs_only"`
30		CondensationID   string    `json:"condensation_id"`
31	}
32	
33	// InitRepo initializes a git repository in the given directory with test user config.
34	func InitRepo(t *testing.T, repoDir string) {
35		t.Helper()
36	
37		repo, err := git.PlainInit(repoDir, false)
38		if err != nil {
39			t.Fatalf("failed to init git repo: %v", err)
40		}
41	
42		// Configure git user for commits
43		cfg, err := repo.Config()
44		if err != nil {
45			t.Fatalf("failed to get repo config: %v", err)
46		}
47		cfg.User.Name = "Test User"
48		cfg.User.Email = "test@example.com"
49	
50		// Disable GPG signing for test commits
51		if cfg.Raw == nil {
52			cfg.Raw = config.New()
53		}
54		cfg.Raw.Section("commit").SetOption("gpgsign", "false")
55		cfg.Core.AutoCRLF = "true"
56	
57		if err := repo.SetConfig(cfg); err != nil {
58			t.Fatalf("failed to set repo config: %v", err)
59		}
60	}
61	
62	// WriteFile creates a file with the given content in the repo directory.
63	// It creates parent directories as needed.
64	func WriteFile(t *testing.T, repoDir, path, content string) {
65		t.Helper()
66	
67		fullPath := filepath.Join(repoDir, path)
68	
69		// Create parent directories
70		dir := filepath.Dir(fullPath)
71		//nolint:gosec // test code, permissions are intentionally standard
72		if err := os.MkdirAll(dir, 0o755); err != nil {
73			t.Fatalf("failed to create directory %s: %v", dir, err)
74		}
75	
76		//nolint:gosec // test code, permissions are intentionally standard
77		if err := os.WriteFile(fullPath, []byte(content), 0o644); err != nil {
78			t.Fatalf("failed to write file %s: %v", path, err)
79		}
80	}
81	
82	// ReadFile reads a file from the repo directory.
83	func ReadFile(t *testing.T, repoDir, path string) string {
84		t.Helper()
85	
86		fullPath := filepath.Join(repoDir, path)
87		//nolint:gosec // test code, path is from test setup
88		data, err := os.ReadFile(fullPath)
89		if err != nil {
90			t.Fatalf("failed to read file %s: %v", path, err)
91		}
92		return string(data)
93	}
94	
95	// TryReadFile reads a file from the repo directory, returning empty string if not found.
96	func TryReadFile(t *testing.T, repoDir, path string) string {
97		t.Helper()
98	
99		fullPath := filepath.Join(repoDir, path)
100		//nolint:gosec // test code, path is from test setup
101		data, err := os.ReadFile(fullPath)
102		if err != nil {
103			return ""
104		}
105		return string(data)
106	}
107	
108	// FileExists checks if a file exists in the repo directory.
109	func FileExists(repoDir, path string) bool {
110		fullPath := filepath.Join(repoDir, path)
111		_, err := os.Stat(fullPath)
112		return err == nil
113	}
114	
115	// GitAdd stages files for commit.
116	func GitAdd(t *testing.T, repoDir string, paths ...string) {
117		t.Helper()
118	
119		repo, err := git.PlainOpen(repoDir)
120		if err != nil {
121			t.Fatalf("failed to open git repo: %v", err)
122		}
123	
124		worktree, err := repo.Worktree()
125		if err != nil {
126			t.Fatalf("failed to get worktree: %v", err)
127		}
128	
129		for _, path := range paths {
130			if _, err := worktree.Add(path); err != nil {
131				t.Fatalf("failed to add file %s: %v", path, err)
132			}
133		}
134	}
135	
136	// GitCommit creates a commit with all staged files.
137	func GitCommit(t *testing.T, repoDir, message string) {
138		t.Helper()
139	
140		repo, err := git.PlainOpen(repoDir)
141		if err != nil {
142			t.Fatalf("failed to open git repo: %v", err)
143		}
144	
145		worktree, err := repo.Worktree()
146		if err != nil {
147			t.Fatalf("failed to get worktree: %v", err)
148		}
149	
150		_, err = worktree.Commit(message, &git.CommitOptions{
151			Author: &object.Signature{
152				Name:  "Test User",
153				Email: "test@example.com",
154				When:  time.Now(),
155			},
156		})
157		if err != nil {
158			t.Fatalf("failed to commit: %v", err)
159		}
160	}
