162	// GitCheckoutNewBranch creates and checks out a new branch.
163	// Uses git CLI to work around go-git v5 bug with checkout deleting untracked files.
164	func GitCheckoutNewBranch(t *testing.T, repoDir, branchName string) {
165		t.Helper()
166	
167		//nolint:noctx // test code, no context needed for git checkout
168		cmd := exec.Command("git", "checkout", "-b", branchName)
169		cmd.Dir = repoDir
170		if output, err := cmd.CombinedOutput(); err != nil {
171			t.Fatalf("failed to checkout new branch %s: %v\nOutput: %s", branchName, err, output)
172		}
173	}
174	
175	// GetHeadHash returns the current HEAD commit hash.
176	func GetHeadHash(t *testing.T, repoDir string) string {
177		t.Helper()
178	
179		repo, err := git.PlainOpen(repoDir)
180		if err != nil {
181			t.Fatalf("failed to open git repo: %v", err)
182		}
183	
184		head, err := repo.Head()
185		if err != nil {
186			t.Fatalf("failed to get HEAD: %v", err)
187		}
188	
189		return head.Hash().String()
190	}
191	
192	// CreateBranch creates a local branch at the current HEAD.
193	func CreateBranch(t *testing.T, dir string, name string) {
194		t.Helper()
195		cmd := exec.Command("git", "branch", name)
196		cmd.Dir = dir
197		cmd.Env = GitIsolatedEnv()
198		if out, err := cmd.CombinedOutput(); err != nil {
199			t.Fatalf("git branch %s: %v\n%s", name, err, out)
200		}
201	}
202	
203	// GitReset runs git reset --hard to the given ref.
204	func GitReset(t *testing.T, dir string, ref string) {
205		t.Helper()
206		cmd := exec.Command("git", "reset", "--hard", ref)
207		cmd.Dir = dir
208		cmd.Env = GitIsolatedEnv()
209		if out, err := cmd.CombinedOutput(); err != nil {
210			t.Fatalf("git reset --hard %s: %v\n%s", ref, err, out)
211		}
212	}
