214	// BranchExists checks if a branch exists in the repository.
215	func BranchExists(t *testing.T, repoDir, branchName string) bool {
216		t.Helper()
217	
218		repo, err := git.PlainOpen(repoDir)
219		if err != nil {
220			t.Fatalf("failed to open git repo: %v", err)
221		}
222	
223		refs, err := repo.References()
224		if err != nil {
225			t.Fatalf("failed to get references: %v", err)
226		}
227	
228		found := false
229		//nolint:errcheck,gosec // ForEach callback doesn't return errors we need to handle
230		refs.ForEach(func(ref *plumbing.Reference) error {
231			if ref.Name().Short() == branchName {
232				found = true
233			}
234			return nil
235		})
236	
237		return found
238	}
239	
240	// GetCommitMessage returns the commit message for the given commit hash.
241	func GetCommitMessage(t *testing.T, repoDir, hash string) string {
242		t.Helper()
243	
244		repo, err := git.PlainOpen(repoDir)
245		if err != nil {
246			t.Fatalf("failed to open git repo: %v", err)
247		}
248	
249		commitHash := plumbing.NewHash(hash)
250		commit, err := repo.CommitObject(commitHash)
251		if err != nil {
252			t.Fatalf("failed to get commit %s: %v", hash, err)
253		}
254	
255		return commit.Message
256	}
